def test():
    slugs = [x["slug"] for x in WORDS]
    assert len(slugs) == len(set(slugs)) >= 16
    for x in WORDS:
        assert len(x["groups"]) == 4 and len(x["qa"]) == 2, x["slug"]
        for what, words, line in x["groups"]:
            assert len(words) == 6 and any(c.isdigit() for c in line) and not line.endswith("."), (x["slug"], what)
            assert line.split()[0].lower().rstrip(",") in [w.split()[0] for w in words] or line.split()[0].lower() in ("ran", "co-designed"), (x["slug"], line)
        for q, a in x["qa"]:
            assert q.endswith("?") and 12 <= len(a.split()) <= 60, (x["slug"], q)
    print(f"resume_words: {len(WORDS)} words, all checks passed")


if __name__ == "__main__":
    test()
